function debounce(callback, delay) {
  let timer;

  return function (...args) {
    clearTimeout(timer);

    timer = setTimeout(() => {
      callback.apply(this, args);
    }, delay);
  };
}

const handleInput = debounce(function (event) {
  console.log(event.target.value);
}, 500);

document
  .querySelector("input")
  .addEventListener("input", handleInput);

